input.oldString:
function draw(){
    // background
    ctx.fillStyle = '#000';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    // stars (optional simple static)
    for(let i=0;i<30;i++){
      ctx.fillStyle = '#555';
      ctx.fillRect(Math.random()*canvas.width, Math.random()*canvas.height, 1,1);
    }
    // ship
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y + ship.h/2);
    ctx.lineTo(ship.x + ship.w, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();
    // asteroids
    ctx.fillStyle = '#a52a2a';
    for(const a of asteroids){
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.size/2, 0, Math.PI*2);
      ctx.fill();
    }
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Distance: '+Math.floor(distance), 10,20);
    if(gameOver){
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,canvas.width,canvas.height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width/2, canvas.height/2);
    }
  }

input.newString:
function draw(){
    // background gradient (space)
    const grad = ctx.createLinearGradient(0,0,0,canvas.height);
    grad.addColorStop(0, '#001');
    grad.addColorStop(1, '#000');
    ctx.fillStyle = grad;
    ctx.fillRect(0,0,canvas.width,canvas.height);
    // starfield twinkling update
    for(const s of stars){
      // random twinkle
      if(Math.random()<0.02) s.bright = !s.bright;
    }
    // starfield draw
    for(const s of stars){
      ctx.fillStyle = s.bright ? '#fff' : '#888';
      ctx.fillRect(s.x, s.y, 2, 2);
    }
    // ship with gradient
    ctx.save();
    ctx.translate(ship.x + ship.w/2, ship.y + ship.h/2);
    const shipGrad = ctx.createLinearGradient(-ship.w/2,0,ship.w/2,0);
    shipGrad.addColorStop(0, '#0f0');
    shipGrad.addColorStop(1, '#080');
    ctx.fillStyle = shipGrad;
    ctx.beginPath();
    ctx.moveTo(-ship.w/2, 0);
    ctx.lineTo(ship.w/2, -ship.h/2);
    ctx.lineTo(ship.w/2, ship.h/2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    // asteroids with irregular polygon
    ctx.fillStyle = '#a52a2a';
    for(const a of asteroids){
      ctx.save();
      ctx.translate(a.x, a.y);
      ctx.rotate(a.speed * 0.1); // slight rotation based on speed
      ctx.beginPath();
      const r = a.size/2;
      for(let i=0;i<7;i++){
        const angle = (i*2*Math.PI)/7;
        const rad = r * (0.5 + Math.random()*0.5);
        ctx.lineTo(Math.cos(angle)*rad, Math.sin(angle)*rad);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // UI
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Distance: '+Math.floor(distance), 10,20);
    if(gameOver){
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,canvas.width,canvas.height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width/2, canvas.height/2);
    }
  }

